INSERT INTO public.listening_lessons (title, level, description, content) VALUES ('Lesson 01 - International Business', 'A1', 'Listening practice for A1 level focusing on International Business.', '{"p1": {"image_url": "https://source.unsplash.com/800x600/?International,Business", "options": [{"text": "A person is discussing international business in a meeting.", "is_correct": true}, {"text": "Someone is working alone on a international business project.", "is_correct": false}, {"text": "A group of people are laughing outdoors.", "is_correct": false}]}, "p2": [{"script": "How often do you deal with international business?", "options": [{"text": "Every single day.", "is_correct": true}, {"text": "I don''t like coffee.", "is_correct": false}, {"text": "It''s about 5 kilometers away.", "is_correct": false}]}, {"script": "How often do you deal with international business?", "options": [{"text": "Every single day.", "is_correct": true}, {"text": "I don''t like coffee.", "is_correct": false}, {"text": "It''s about 5 kilometers away.", "is_correct": false}]}, {"script": "How often do you deal with international business?", "options": [{"text": "Every single day.", "is_correct": true}, {"text": "I don''t like coffee.", "is_correct": false}, {"text": "It''s about 5 kilometers away.", "is_correct": false}]}], "p3": {"script": "Speaker A: I think our strategy for international business needs to change.\nSpeaker B: I agree. We should focus more on efficiency.\nSpeaker A: Let''s schedule a meeting for tomorrow morning.", "questions": [{"enunciado": "What are they discussing?", "options": [{"text": "A change in international business strategy.", "is_correct": true}, {"text": "A new office location.", "is_correct": false}, {"text": "Their lunch plans.", "is_correct": false}]}, {"enunciado": "What are they discussing?", "options": [{"text": "A change in international business strategy.", "is_correct": true}, {"text": "A new office location.", "is_correct": false}, {"text": "Their lunch plans.", "is_correct": false}]}, {"enunciado": "What are they discussing?", "options": [{"text": "A change in international business strategy.", "is_correct": true}, {"text": "A new office location.", "is_correct": false}, {"text": "Their lunch plans.", "is_correct": false}]}]}, "p4": {"script": "In today''s global market, International Business has become a cornerstone of success. Companies that invest in proper training and technology often see a 20% increase in productivity. However, the human element remains the most important factor in long-term growth.", "questions": [{"enunciado": "What is the main topic of the talk?", "options": [{"text": "The importance of International Business.", "is_correct": true}, {"text": "The history of the internet.", "is_correct": false}, {"text": "How to cook a traditional meal.", "is_correct": false}]}, {"enunciado": "What is the main topic of the talk?", "options": [{"text": "The importance of International Business.", "is_correct": true}, {"text": "The history of the internet.", "is_correct": false}, {"text": "How to cook a traditional meal.", "is_correct": false}]}, {"enunciado": "What is the main topic of the talk?", "options": [{"text": "The importance of International Business.", "is_correct": true}, {"text": "The history of the internet.", "is_correct": false}, {"text": "How to cook a traditional meal.", "is_correct": false}]}]}}');
